-- mod-guild-adventure: talent templates per class (GA_world). GENERATED by tools/gen_spec_templates.py from the
-- talent profiles of the wowbot335 repository (profiles/talents); edit the profiles or the script, not this file.
-- Applied by the worldserver's DB updater (re-applied when the file changes); every statement is idempotent.
-- Reload at runtime with ".ga reload". Design: docs/specs.md.
--
-- points: one token per talent point in the order they are spent (level 10 first), "tab.row.column" (all from 0).
-- The level-60 part (51 points, this server's cap) holds the talents the spec is played with: every active talent
-- the profile takes, the last talent of a tree with the first 50 points and a few the profile lacks that
-- mod-playerbots' rotation casts come at the earliest point their tier allows (KEY_ADDITIONS in the script).
-- purpose: 0 leveling, 1 dungeon and raid, 3 PvP. role: 0 damage, 1 tank, 2 healer. is_default: the template of
-- the class when the guild leader chose none.
CREATE TABLE IF NOT EXISTS `ga_spec_template` (
    `id`         INT UNSIGNED     NOT NULL,
    `class`      TINYINT UNSIGNED NOT NULL COMMENT 'ChrClasses.dbc id',
    `code`       VARCHAR(48)      NOT NULL,
    `name`       VARCHAR(48)      NOT NULL,
    `purpose`    TINYINT UNSIGNED NOT NULL DEFAULT 0,
    `role`       TINYINT UNSIGNED NOT NULL DEFAULT 0,
    `tab`        TINYINT UNSIGNED NOT NULL DEFAULT 0 COMMENT 'the tree with most points at level 60',
    `is_default` TINYINT UNSIGNED NOT NULL DEFAULT 0,
    `points`     TEXT             NOT NULL,
    PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COMMENT='Guild Adventure: talent templates per class';

DELETE FROM `ga_spec_template`;
